// auth.store.ts
interface AuthState { user: { name: string } | null; loading: boolean; }

@Injectable({ providedIn: 'root' })
export class AuthStore {
  private state = new BehaviorSubject<AuthState>({ user: null, loading: false });
  user$ = this.state.pipe(map(s => s.user), distinctUntilChanged());
  isLoggedIn$ = this.user$.pipe(map(user => !!user));
  loading$ = this.state.pipe(map(s => s.loading));

  login(username: string, password: string) {
    // Optimistic update
    this.state.next({ user: { name: username }, loading: true });

    of(true).pipe(delay(1000)).subscribe({
      next: () => {
        // Success – update with real data (simulated)
        this.state.next({ user: { name: username }, loading: false });
      },
      error: () => {
        // Failure – rollback
        this.state.next({ user: null, loading: false });
      }
    });
  }

  logout() {
    this.state.next({ user: null, loading: false });
  }
}
